    public void init()
    {
        xArgs args = this.args();

        GUPPriceComponentCode priceComponentCode = args.record();

        if (!priceComponentCode.RecId)
        {
            error("@SYS22539");
            this.close();
            return;
        }

        super();

        PriceComponentCodeControl.text(priceComponentCode.Name);

        this.fillTree(priceComponentCode.RecId);

        // Hide default filter button.
        this.control(this.controlId('SystemDefinedShowFiltersButton')).visible(false);
    }

private void setTreeItemExpanded(TreeItemIdx _idx, boolean expanded = true)
{
    FormTreeItem ti = ReportTree.getItem(_idx);
    ti.stateExpanded(expanded);
    ReportTree.setItem(ti);
}

private RecId insertNewHierarchyItem(GUPPriceAttributeGroupPriorityHierarchyViewTmpItem _hierarchyTmpTable,
                                     GUPPricingAttributeGroupName                       _attributeGroupName,
                                     Description                                        _description,
                                     GUPPricingAttributeSourceLevel                     _sourceLevel, 
                                     GUPPriceAttributeGroupPriority                     _priority)
{
    _hierarchyTmpTable.PriceAttributeGroup            = GUPPricingAttributeGroup::findByName(_attributeGroupName).RecId;
    _hierarchyTmpTable.PriceAttributeGroupName        = _attributeGroupName;
    _hierarchyTmpTable.PriceAttributeGroupDescription = _description;
    _hierarchyTmpTable.SourceLevel                    = _sourceLevel;
    _hierarchyTmpTable.Priority                       = _priority;
    _hierarchyTmpTable.insert();
    return _hierarchyTmpTable.RecId;
}

    private void fillTree(RecId _argComponentCodeRecId)
    {
        ReportTree.lock();
        GUPPriceComponentCode argRecord;
        GUPPriceAttributeGroupPriorityHierarchyViewTmpItem hierarchyHeaderItems, hierarchyLineItems;

        GUPPriceComponentCodePriceAttributeGroupSelection groupSelection;
        GUPPricingAttributeGroup attributeGroup;

        select firstonly Name, RecId, HeaderPriceAttributeGroupAllEnabled, LinePriceAttributeGroupAllEnabled
            from argRecord where argRecord.RecId == _argComponentCodeRecId;

        TreeItemIdx rootIdx = SysFormTreeControl::addTreeItem(ReportTree, argRecord.Name, FormTreeAdd::Root, 0);
        this.setTreeItemExpanded(rootIdx);

        while select PriceAttributeGroupName, SourceLevel, Priority from groupSelection
            order by groupSelection.Priority desc
            where groupSelection.PriceComponentCodeName == argRecord.Name
            join Name, Description from attributeGroup
                where attributeGroup.Name == groupSelection.PriceAttributeGroupName
        {
            this.insertNewHierarchyItem(groupSelection.SourceLevel == GUPPricingAttributeSourceLevel::Header ? hierarchyHeaderItems : hierarchyLineItems,
                                        attributeGroup.Name,
                                        attributeGroup.Description,
                                        groupSelection.SourceLevel,
                                        groupSelection.Priority);
        }

        if (argRecord.HeaderPriceAttributeGroupAllEnabled == NoYes::Yes)
        {
            // Insert item for "all" headers.
            this.insertNewHierarchyItem(hierarchyHeaderItems,
                                        "@GlobalUnifiedPricing:GUPPriceAttributeGroupSelectionAll",
                                        '',
                                        GUPPricingAttributeSourceLevel::Header,
                                        intMin());
        }

        if (argRecord.LinePriceAttributeGroupAllEnabled == NoYes::Yes)
        {
            // Insert item for "all" lines.
            this.insertNewHierarchyItem(hierarchyLineItems,
                                        "@GlobalUnifiedPricing:GUPPriceAttributeGroupSelectionAll",
                                        '',
                                        GUPPricingAttributeSourceLevel::Line,
                                        intMin());
        }

        int headerCount = 0;

        // Order by AttributeGroup RecId to break ties.
        while select hierarchyHeaderItems order by Priority desc, PriceAttributeGroup desc
        {
            headerCount++;

            var newItemRecId = this.insertNewHierarchyItem(GUPPriceAttributeGroupPriorityHierarchyViewTmpItem,
                                                           hierarchyHeaderItems.PriceAttributeGroupName,
                                                           hierarchyHeaderItems.PriceAttributeGroupDescription,
                                                           hierarchyHeaderItems.SourceLevel,
                                                           hierarchyHeaderItems.Priority);

            TreeItemIdx currentParentIdx = SysFormTreeControl::addTreeItem(ReportTree, 
                                                                           hierarchyHeaderItems.PriceAttributeGroupName,
                                                                           rootIdx,
                                                                           newItemRecId);

            while select hierarchyLineItems order by Priority desc, PriceAttributeGroup desc
            {
                newItemRecId = this.insertNewHierarchyItem(GUPPriceAttributeGroupPriorityHierarchyViewTmpItem,
                                                           hierarchyLineItems.PriceAttributeGroupName,
                                                           hierarchyLineItems.PriceAttributeGroupDescription,
                                                           hierarchyLineItems.SourceLevel,
                                                           hierarchyLineItems.Priority);

                SysFormTreeControl::addTreeItem(ReportTree,
                                                hierarchyLineItems.PriceAttributeGroupName,
                                                currentParentIdx,
                                                newItemRecId);
            }

            this.setTreeItemExpanded(currentParentIdx);
        }

        // Set priority for "All" header and lines back to zero after establishing the item order.
        update_recordset GUPPriceAttributeGroupPriorityHierarchyViewTmpItem
            setting Priority = 0
            where GUPPriceAttributeGroupPriorityHierarchyViewTmpItem.Priority == intMin();

        if (headerCount <= 1)
        {
            // If there is no header group with priority or description to show, hide the related fields.
            AttributeGroupDescriptionControl.visible(false);
        }

        ReportTree.unlock(true);
    }

        public void selectionChanged(FormTreeItem _OldItem, FormTreeItem _NewItem, FormTreeSelect _how)
        {
            GUPPriceAttributeGroupPriorityHierarchyViewTmpItem  hierarchyTmpItemFind;

        	super(_OldItem, _NewItem, _how);

            GUPPricingAttributeGroupRecId selectedRecId = _NewItem.data();
            hierarchyTmpItemFind.linkPhysicalTableInstance(GUPPriceAttributeGroupPriorityHierarchyViewTmpItem);

            select firstonly hierarchyTmpItemFind where hierarchyTmpItemFind.RecId == selectedRecId;

            if (hierarchyTmpItemFind)
            {
                element.args().lookupRecord(hierarchyTmpItemFind);
                GUPPriceAttributeGroupPriorityHierarchyViewTmpItem_ds.research(false);
            }
        }
